package com.google.common.collect;

import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.assertThrows;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.function.Function;
import org.junit.Test;

public class IteratorsTransformJdkFunctionTest {

    @Test
    public void testTransformBasic() {
        List<String> source = Arrays.asList("a", "b", "c");
        Iterator<String> sourceIterator = source.iterator();
        Function<String, String> toUpperCase = String::toUpperCase;
        Iterator<String> transformed = Iterators.transform(sourceIterator, toUpperCase);

        List<String> result = new ArrayList<>();
        while (transformed.hasNext()) {
            result.add(transformed.next());
        }
        assertThat(result).containsExactly("A", "B", "C").inOrder();
    }

    @Test
    public void testTransformWithNulls() {
        List<String> source = Arrays.asList("a", null, "c");
        Iterator<String> sourceIterator = source.iterator();
        Function<String, String> identity = Function.identity();
        Iterator<String> transformed = Iterators.transform(sourceIterator, identity);

        List<String> result = new ArrayList<>();
        while (transformed.hasNext()) {
            result.add(transformed.next());
        }
        assertThat(result).containsExactly("a", null, "c").inOrder();
    }

    @Test
    public void testTransformEmptyIterator() {
        List<String> source = new ArrayList<>();
        Iterator<String> sourceIterator = source.iterator();
        Function<String, Integer> length = String::length;
        Iterator<Integer> transformed = Iterators.transform(sourceIterator, length);

        assertThat(transformed.hasNext()).isFalse();
        assertThrows(NoSuchElementException.class, transformed::next);
    }

    @Test
    public void testTransformRemove() {
        List<String> source = new ArrayList<>(Arrays.asList("a", "b", "c"));
        Iterator<String> sourceIterator = source.iterator();
        Function<String, String> toUpperCase = String::toUpperCase;
        Iterator<String> transformed = Iterators.transform(sourceIterator, toUpperCase);

        assertThat(transformed.next()).isEqualTo("A");
        transformed.remove(); // Should remove "a" from the underlying source
        assertThat(source).containsExactly("b", "c").inOrder();

        assertThat(transformed.next()).isEqualTo("B");
        transformed.remove(); // Should remove "b"
        assertThat(source).containsExactly("c").inOrder();

        assertThat(transformed.next()).isEqualTo("C");
        transformed.remove(); // Should remove "c"
        assertThat(source).isEmpty();
        assertThat(transformed.hasNext()).isFalse();
    }

    @Test
    public void testTransformRemoveWithoutNextThrows() {
        List<String> source = new ArrayList<>(Arrays.asList("a", "b"));
        Iterator<String> sourceIterator = source.iterator();
        Function<String, String> identity = Function.identity();
        Iterator<String> transformed = Iterators.transform(sourceIterator, identity);

        assertThrows(IllegalStateException.class, transformed::remove);
    }

    @Test
    public void testTransformRemoveAfterHasNext() {
        List<String> source = new ArrayList<>(Arrays.asList("a", "b"));
        Iterator<String> sourceIterator = source.iterator();
        Function<String, String> identity = Function.identity();
        Iterator<String> transformed = Iterators.transform(sourceIterator, identity);

        assertThat(transformed.hasNext()).isTrue();
        assertThrows(IllegalStateException.class, transformed::remove);
    }

    @Test
    public void testTransformFunctionThrows() {
        List<String> source = Arrays.asList("a", "b", "c");
        Iterator<String> sourceIterator = source.iterator();
        Function<String, String> throwingFunction = s -> {
            if (s.equals("b")) {
                throw new RuntimeException("Expected exception");
            }
            return s.toUpperCase();
        };
        Iterator<String> transformed = Iterators.transform(sourceIterator, throwingFunction);

        assertThat(transformed.next()).isEqualTo("A");
        RuntimeException e = assertThrows(RuntimeException.class, transformed::next);
        assertThat(e).hasMessageThat().isEqualTo("Expected exception");
    }

    @Test
    public void testTransformNullFunction() {
        List<String> source = Arrays.asList("a", "b");
        Iterator<String> sourceIterator = source.iterator();
        assertThrows(NullPointerException.class, () -> Iterators.transform(sourceIterator, null));
    }

    @Test
    public void testTransformTypeChange() {
        List<Integer> source = Arrays.asList(1, 2, 3);
        Iterator<Integer> sourceIterator = source.iterator();
        Function<Integer, String> toString = Object::toString;
        Iterator<String> transformed = Iterators.transform(sourceIterator, toString);

        List<String> result = new ArrayList<>();
        while (transformed.hasNext()) {
            result.add(transformed.next());
        }
        assertThat(result).containsExactly("1", "2", "3").inOrder();
    }

    @Test
    public void testTransformWithLambda() {
        List<Integer> source = Arrays.asList(1, 2, 3);
        Iterator<Integer> sourceIterator = source.iterator();
        Iterator<String> transformed = Iterators.transform(sourceIterator, i -> "#" + i);

        List<String> result = new ArrayList<>();
        while (transformed.hasNext()) {
            result.add(transformed.next());
        }
        assertThat(result).containsExactly("#1", "#2", "#3").inOrder();
    }

    @Test
    public void testTransformWithMethodReference() {
        List<String> source = Arrays.asList("apple", "banana", "cherry");
        Iterator<String> sourceIterator = source.iterator();
        Iterator<Integer> transformed = Iterators.transform(sourceIterator, String::length);

        List<Integer> result = new ArrayList<>();
        while (transformed.hasNext()) {
            result.add(transformed.next());
        }
        assertThat(result).containsExactly(5, 6, 6).inOrder();
    }
}

