package com.google.common.util.concurrent;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.IOException;
import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;

/**
 * Unit tests for {@link RetryExecutor}.
 */
public class RetryExecutorTest {

    @Test
    public void testExecute_successOnFirstAttempt() throws Exception {
        RetryExecutor executor = RetryExecutor.builder().maxRetries(3).build();
        String result = executor.execute(() -> "success");
        assertEquals("success", result);
    }

    @Test
    public void testExecute_retryAndSuccess() throws Exception {
        AtomicInteger attempts = new AtomicInteger(0);
        RetryExecutor executor = RetryExecutor.builder().maxRetries(3).backoffMillis(10).build();
        String result = executor.execute(() -> {
            if (attempts.incrementAndGet() < 2) {
                throw new IOException("Temporary failure");
            }
            return "success";
        });
        assertEquals(2, attempts.get());
        assertEquals("success", result);
    }

    @Test
    public void testExecute_exhaustRetries() {
        AtomicInteger attempts = new AtomicInteger(0);
        RetryExecutor executor = RetryExecutor.builder().maxRetries(3).backoffMillis(10).build();
        Exception expected = assertThrows(IOException.class, () -> executor.execute(() -> {
            attempts.incrementAndGet();
            throw new IOException("Persistent failure");
        }));
        assertEquals(3, attempts.get());
        assertEquals("Persistent failure", expected.getMessage());
    }

    @Test
    public void testExecute_nonRetryableException() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .retryOn(IOException.class)
                .build();
        AtomicInteger attempts = new AtomicInteger(0);
        RuntimeException nonRetryable = new RuntimeException("Non-retryable");
        Exception thrown = assertThrows(RuntimeException.class, () -> executor.execute(() -> {
            attempts.incrementAndGet();
            throw nonRetryable;
        }));
        assertEquals(1, attempts.get());
        assertEquals(nonRetryable, thrown);
    }

    @Test
    public void testExecute_exponentialBackoff() throws Exception {
        AtomicInteger attempts = new AtomicInteger(0);
        long startTime = System.currentTimeMillis();
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(100)
                .exponentialBackoff(true)
                .build();
        String result = executor.execute(() -> {
            if (attempts.incrementAndGet() < 3) {
                throw new IOException("Temporary failure");
            }
            return "success";
        });
        long elapsed = System.currentTimeMillis() - startTime;
        // Expected delays: attempt 0 -> 100ms, attempt 1 -> 200ms, total ~300ms
        assertTrue("Elapsed time should be at least 300ms (due to exponential backoff), but was " + elapsed,
                elapsed >= 300);
        assertEquals(3, attempts.get());
        assertEquals("success", result);
    }

    @Test
    public void testExecute_fixedBackoff() throws Exception {
        AtomicInteger attempts = new AtomicInteger(0);
        long startTime = System.currentTimeMillis();
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(50)
                .exponentialBackoff(false)
                .build();
        String result = executor.execute(() -> {
            if (attempts.incrementAndGet() < 3) {
                throw new IOException("Temporary failure");
            }
            return "success";
        });
        long elapsed = System.currentTimeMillis() - startTime;
        // Expected delays: 50ms each for two failures, total ~100ms
        assertTrue("Elapsed time should be at least 100ms (due to fixed backoff), but was " + elapsed,
                elapsed >= 100);
        assertEquals(3, attempts.get());
        assertEquals("success", result);
    }

    @Test
    public void testExecute_interruptedDuringSleep() throws Exception {
        RetryExecutor executor = RetryExecutor.builder().maxRetries(3).backoffMillis(1000).build();
        AtomicInteger attempts = new AtomicInteger(0);
        Thread testThread = Thread.currentThread();
        // Schedule an interrupt after a short delay
        new Thread(() -> {
            try {
                Thread.sleep(100);
                testThread.interrupt();
            } catch (InterruptedException e) {
                // ignore
            }
        }).start();

        IOException expected = new IOException("Expected");
        Exception thrown = assertThrows(IOException.class, () -> executor.execute(() -> {
            attempts.incrementAndGet();
            throw expected;
        }));
        // Should have been interrupted during sleep after first attempt
        assertEquals(1, attempts.get());
        assertEquals(expected, thrown);
        // Clear interrupt status
        Thread.interrupted();
    }

    @Test
    public void testExecute_nullTask() {
        RetryExecutor executor = RetryExecutor.builder().build();
        assertThrows(NullPointerException.class, () -> executor.execute(null));
    }

    @Test
    public void testBuilder_defaults() {
        RetryExecutor executor = RetryExecutor.builder().build();
        // Default maxRetries is 3, backoffMillis is 1000, exponentialBackoff false, retryableExceptions empty
        AtomicInteger attempts = new AtomicInteger(0);
        Exception thrown = assertThrows(IOException.class, () -> executor.execute(() -> {
            attempts.incrementAndGet();
            throw new IOException("Fail");
        }));
        assertEquals(3, attempts.get());
    }

    @Test
    public void testBuilder_validation() {
        // maxRetries must be positive
        IllegalArgumentException e1 = assertThrows(IllegalArgumentException.class,
                () -> RetryExecutor.builder().maxRetries(0).build());
        assertEquals("maxRetries must be positive", e1.getMessage());
        // backoffMillis must be non-negative
        IllegalArgumentException e2 = assertThrows(IllegalArgumentException.class,
                () -> RetryExecutor.builder().backoffMillis(-1).build());
        assertEquals("backoffMillis must be non-negative", e2.getMessage());
    }

    @Test
    public void testExecute_retryOnSpecificException() throws Exception {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .retryOn(IOException.class)
                .retryOn(IllegalStateException.class)
                .build();
        AtomicInteger attempts = new AtomicInteger(0);
        String result = executor.execute(() -> {
            attempts.incrementAndGet();
            if (attempts.get() == 1) throw new IOException("IO");
            if (attempts.get() == 2) throw new IllegalStateException("State");
            return "done";
        });
        assertEquals(3, attempts.get());
        assertEquals("done", result);
    }

    @Test
    public void testExecute_noRetryableExceptionsConfigured_retriesAll() throws Exception {
        RetryExecutor executor = RetryExecutor.builder().maxRetries(3).build();
        AtomicInteger attempts = new AtomicInteger(0);
        String result = executor.execute(() -> {
            attempts.incrementAndGet();
            if (attempts.get() < 3) throw new CustomException("Custom");
            return "ok";
        });
        assertEquals(3, attempts.get());
        assertEquals("ok", result);
    }

    private static class CustomException extends Exception {
        CustomException(String msg) {
            super(msg);
        }
    }
}

