package com.google.common.util.concurrent;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;

/**
 * Unit tests for {@link RetryExecutor}.
 */
public class RetryExecutorTest {

    @Test
    public void testBuilderReturnsNonNullInstance() {
        RetryExecutor.Builder builder = RetryExecutor.builder();
        assertNotNull(builder);
    }

    @Test
    public void testBuilderDefaultValues() {
        RetryExecutor executor = RetryExecutor.builder().build();
        // Use reflection to verify default values, or test via behavior
        // Since fields are private, we test through execution behavior
        AtomicInteger attempts = new AtomicInteger(0);
        Callable<String> failingTask = () -> {
            attempts.incrementAndGet();
            throw new IOException("Simulated failure");
        };

        Exception e = assertThrows(IOException.class, () -> executor.execute(failingTask));
        // Default maxRetries is 3, so total attempts should be 3 (initial + 2 retries)
        assertEquals(3, attempts.get());
    }

    @Test
    public void testBuilderWithCustomMaxRetries() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(5)
                .build();

        AtomicInteger attempts = new AtomicInteger(0);
        Callable<String> failingTask = () -> {
            attempts.incrementAndGet();
            throw new RuntimeException("Fail");
        };

        Exception e = assertThrows(RuntimeException.class, () -> executor.execute(failingTask));
        assertEquals(5, attempts.get());
    }

    @Test
    public void testBuilderWithBackoffMillis() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(2)
                .backoffMillis(500)
                .build();

        long startTime = System.currentTimeMillis();
        AtomicInteger attempts = new AtomicInteger(0);
        Callable<String> failingTask = () -> {
            attempts.incrementAndGet();
            throw new Exception("Fail");
        };

        assertThrows(Exception.class, () -> executor.execute(failingTask));
        long elapsed = System.currentTimeMillis() - startTime;
        // Should have slept at least once for 500ms (fixed backoff)
        assertTrue(elapsed >= 500);
        assertEquals(2, attempts.get());
    }

    @Test
    public void testBuilderWithExponentialBackoff() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(100)
                .exponentialBackoff(true)
                .build();

        long startTime = System.currentTimeMillis();
        AtomicInteger attempts = new AtomicInteger(0);
        Callable<String> failingTask = () -> {
            attempts.incrementAndGet();
            throw new Exception("Fail");
        };

        assertThrows(Exception.class, () -> executor.execute(failingTask));
        long elapsed = System.currentTimeMillis() - startTime;
        // Exponential delays: attempt0 delay 100, attempt1 delay 200, total >=300
        assertTrue(elapsed >= 300);
        assertEquals(3, attempts.get());
    }

    @Test
    public void testBuilderWithRetryOnSpecificException() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(2)
                .retryOn(IOException.class)
                .build();

        AtomicInteger attempts = new AtomicInteger(0);
        Callable<String> ioExceptionTask = () -> {
            attempts.incrementAndGet();
            throw new IOException("IO error");
        };

        Exception e = assertThrows(IOException.class, () -> executor.execute(ioExceptionTask));
        // Should retry on IOException
        assertEquals(2, attempts.get());

        // Non-retryable exception should not be retried
        AtomicInteger attempts2 = new AtomicInteger(0);
        Callable<String> runtimeExceptionTask = () -> {
            attempts2.incrementAndGet();
            throw new RuntimeException("Runtime error");
        };

        Exception e2 = assertThrows(RuntimeException.class, () -> executor.execute(runtimeExceptionTask));
        // Should not retry (only one attempt)
        assertEquals(1, attempts2.get());
    }

    @Test
    public void testBuilderWithMultipleRetryOnExceptions() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(2)
                .retryOn(IOException.class)
                .retryOn(IllegalArgumentException.class)
                .build();

        AtomicInteger attempts = new AtomicInteger(0);
        Callable<String> ioExceptionTask = () -> {
            attempts.incrementAndGet();
            throw new IOException("IO error");
        };

        assertThrows(IOException.class, () -> executor.execute(ioExceptionTask));
        assertEquals(2, attempts.get());

        AtomicInteger attempts2 = new AtomicInteger(0);
        Callable<String> illegalArgTask = () -> {
            attempts2.incrementAndGet();
            throw new IllegalArgumentException("Illegal argument");
        };

        assertThrows(IllegalArgumentException.class, () -> executor.execute(illegalArgTask));
        assertEquals(2, attempts2.get());

        // Other exceptions should not be retried
        AtomicInteger attempts3 = new AtomicInteger(0);
        Callable<String> runtimeExceptionTask = () -> {
            attempts3.incrementAndGet();
            throw new RuntimeException("Runtime error");
        };

        assertThrows(RuntimeException.class, () -> executor.execute(runtimeExceptionTask));
        assertEquals(1, attempts3.get());
    }

    @Test
    public void testBuilderValidation() {
        // maxRetries must be positive
        IllegalArgumentException e1 = assertThrows(IllegalArgumentException.class,
                () -> RetryExecutor.builder().maxRetries(0).build());
        assertEquals("maxRetries must be positive", e1.getMessage());

        // backoffMillis must be non-negative
        IllegalArgumentException e2 = assertThrows(IllegalArgumentException.class,
                () -> RetryExecutor.builder().backoffMillis(-1).build());
        assertEquals("backoffMillis must be non-negative", e2.getMessage());
    }

    @Test
    public void testBuilderChain() {
        RetryExecutor.Builder builder = RetryExecutor.builder()
                .maxRetries(10)
                .backoffMillis(2000)
                .exponentialBackoff(true)
                .retryOn(IOException.class);

        RetryExecutor executor = builder.build();
        assertNotNull(executor);
    }

    @Test
    public void testSuccessfulExecutionWithoutRetry() throws Exception {
        RetryExecutor executor = RetryExecutor.builder().maxRetries(3).build();
        Callable<String> successTask = () -> "success";
        String result = executor.execute(successTask);
        assertEquals("success", result);
    }

    @Test
    public void testNullTaskThrowsNullPointerException() {
        RetryExecutor executor = RetryExecutor.builder().build();
        assertThrows(NullPointerException.class, () -> executor.execute(null));
    }
}

