package com.google.common.primitives;

import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.assertTrue;

import java.util.Iterator;
import java.util.List;
import java.util.PrimitiveIterator;
import java.util.Spliterator;
import org.junit.Test;

public class ImmutablePrimitiveArrayAsListTest {

  @Test
  public void testImmutableIntArrayAsListIterator() {
    ImmutableIntArray intArray = ImmutableIntArray.of(1, 2, 3);
    List<Integer> list = intArray.asList();

    // Check that iterator is a PrimitiveIterator.OfInt
    Iterator<Integer> iterator = list.iterator();
    assertTrue(iterator instanceof PrimitiveIterator.OfInt);

    PrimitiveIterator.OfInt primitiveIterator = (PrimitiveIterator.OfInt) iterator;
    // Verify iteration
    assertTrue(primitiveIterator.hasNext());
    assertThat(primitiveIterator.nextInt()).isEqualTo(1);
    assertTrue(primitiveIterator.hasNext());
    assertThat(primitiveIterator.nextInt()).isEqualTo(2);
    assertTrue(primitiveIterator.hasNext());
    assertThat(primitiveIterator.nextInt()).isEqualTo(3);
    assertThat(primitiveIterator.hasNext()).isFalse();

    // Also test spliterator is of primitive type
    Spliterator<Integer> spliterator = list.spliterator();
    assertTrue(spliterator instanceof Spliterator.OfInt);
  }

  @Test
  public void testImmutableLongArrayAsListIterator() {
    ImmutableLongArray longArray = ImmutableLongArray.of(1L, 2L, 3L);
    List<Long> list = longArray.asList();

    Iterator<Long> iterator = list.iterator();
    assertTrue(iterator instanceof PrimitiveIterator.OfLong);

    PrimitiveIterator.OfLong primitiveIterator = (PrimitiveIterator.OfLong) iterator;
    assertTrue(primitiveIterator.hasNext());
    assertThat(primitiveIterator.nextLong()).isEqualTo(1L);
    assertTrue(primitiveIterator.hasNext());
    assertThat(primitiveIterator.nextLong()).isEqualTo(2L);
    assertTrue(primitiveIterator.hasNext());
    assertThat(primitiveIterator.nextLong()).isEqualTo(3L);
    assertThat(primitiveIterator.hasNext()).isFalse();

    Spliterator<Long> spliterator = list.spliterator();
    assertTrue(spliterator instanceof Spliterator.OfLong);
  }

  @Test
  public void testImmutableDoubleArrayAsListIterator() {
    ImmutableDoubleArray doubleArray = ImmutableDoubleArray.of(1.0, 2.0, 3.0);
    List<Double> list = doubleArray.asList();

    Iterator<Double> iterator = list.iterator();
    assertTrue(iterator instanceof PrimitiveIterator.OfDouble);

    PrimitiveIterator.OfDouble primitiveIterator = (PrimitiveIterator.OfDouble) iterator;
    assertTrue(primitiveIterator.hasNext());
    assertThat(primitiveIterator.nextDouble()).isEqualTo(1.0);
    assertTrue(primitiveIterator.hasNext());
    assertThat(primitiveIterator.nextDouble()).isEqualTo(2.0);
    assertTrue(primitiveIterator.hasNext());
    assertThat(primitiveIterator.nextDouble()).isEqualTo(3.0);
    assertThat(primitiveIterator.hasNext()).isFalse();

    Spliterator<Double> spliterator = list.spliterator();
    assertTrue(spliterator instanceof Spliterator.OfDouble);
  }

  // Additional test to verify that the iterator can be used in a legacy API scenario
  @Test
  public void testLegacyApiWithPrimitiveIterator() {
    // Simulate a legacy API that accepts List<Double>
    List<Double> scores = ImmutableDoubleArray.of(1.5, 2.5, 3.5).asList();
    double sum = 0.0;
    Iterator<Double> iterator = scores.iterator();
    if (iterator instanceof PrimitiveIterator.OfDouble) {
      PrimitiveIterator.OfDouble pi = (PrimitiveIterator.OfDouble) iterator;
      while (pi.hasNext()) {
        sum += pi.nextDouble(); // no boxing
      }
    } else {
      while (iterator.hasNext()) {
        sum += iterator.next(); // boxing
      }
    }
    assertThat(sum).isEqualTo(7.5);
  }
}

