import java.util.PrimitiveIterator;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

@RunWith(JUnit4.class)
public class ImmutableIntArrayAsListIteratorTest {

  @Test
  public void testIteratorReturnsPrimitiveIteratorOfInt() {
    ImmutableIntArray array = ImmutableIntArray.of(1, 2, 3);
    List<Integer> list = array.asList();
    Iterator<Integer> iterator = list.iterator();
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfInt.class);
  }

  @Test
  public void testPrimitiveIteratorHasNextAndNextInt() {
    ImmutableIntArray array = ImmutableIntArray.of(10, 20, 30);
    List<Integer> list = array.asList();
    PrimitiveIterator.OfInt primitiveIterator = (PrimitiveIterator.OfInt) list.iterator();

    assertThat(primitiveIterator.hasNext()).isTrue();
    assertThat(primitiveIterator.nextInt()).isEqualTo(10);
    assertThat(primitiveIterator.hasNext()).isTrue();
    assertThat(primitiveIterator.nextInt()).isEqualTo(20);
    assertThat(primitiveIterator.hasNext()).isTrue();
    assertThat(primitiveIterator.nextInt()).isEqualTo(30);
    assertThat(primitiveIterator.hasNext()).isFalse();
  }

  @Test
  public void testPrimitiveIteratorNextIntThrowsWhenExhausted() {
    ImmutableIntArray array = ImmutableIntArray.of(5);
    List<Integer> list = array.asList();
    PrimitiveIterator.OfInt primitiveIterator = (PrimitiveIterator.OfInt) list.iterator();

    primitiveIterator.nextInt();
    assertThrows(NoSuchElementException.class, primitiveIterator::nextInt);
  }

  @Test
  public void testPrimitiveIteratorNextBoxed() {
