package com.google.common.hash;

import static com.google.common.base.Preconditions.checkArgument;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.google.common.base.Preconditions;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

@RunWith(JUnit4.class)
public class HashingTest {
    @Test
    public void testConsistentHash_singleBucketAlwaysReturnsZero() {
        // With only one bucket, the result must always be 0.
        for (long input = 0; input < 1000; input++) {
            assertEquals(0, Hashing.consistentHash(input, 1));
        }
        // Also test negative inputs (the method accepts any long).
        for (long input = -1000; input < 0; input++) {
            assertEquals(0, Hashing.consistentHash(input, 1));
        }
    }

    @Test
    public void testConsistentHash_largeBucketCountResultInRange() {
        // For a large number of buckets, the result must be within [0, buckets).
        int buckets = 10000;
        for (long input = 0; input < 1000; input++) {
            int result = Hashing.consistentHash(input, buckets);
            assertTrue("Result " + result + " out of range for buckets=" + buckets,
                    result >= 0 && result < buckets);
        }
    }

    @Test
    public void testConsistentHash_negativeInput() {
        // The method should handle negative inputs correctly.
        int buckets = 10;
        for (long input = -100; input < 0; input++) {
            int result = Hashing.consistentHash(input, buckets);
            assertTrue(result >= 0 && result < buckets);
        }
    }

    @Test
    public void testConsistentHash_zeroBucketsThrows() {
        try {
            Hashing.consistentHash(42L, 0);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
            // expected
        }
    }

    @Test
    public void testConsistentHash_negativeBucketsThrows() {
        try {
            Hashing.consistentHash(42L, -5);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
            // expected
        }
    }

    @Test
    public void testConsistentHash_deterministic() {
        // Same input and buckets should always produce the same output.
        long input = 123456789L;
        int buckets = 50;
        int first = Hashing.consistentHash(input, buckets);
        for (int i = 0; i < 10; i++) {
            assertEquals(first, Hashing.consistentHash(input, buckets));
        }
    }

    @Test
    public void testConsistentHash_arithmeticEdgeCases() {
        // Test specific edge cases for the inlined arithmetic operations

        // Test that state calculation handles overflow correctly
        // The constant 2862933555777941757L is large, so multiplication can overflow

        // Test with 0 input
        assertEquals(0, Hashing.consistentHash(0L, 1));
        int result0 = Hashing.consistentHash(0L, 10);
        assertTrue(result0 >= 0 && result0 < 10);

        // Test with 1 input (common case)
        int result1 = Hashing.consistentHash(1L, 10);
        assertTrue(result1 >= 0 && result1 < 10);

        // Test with -1 input
        int resultNeg1 = Hashing.consistentHash(-1L, 10);
        assertTrue(resultNeg1 >= 0 && resultNeg1 < 10);

        // Test with max long
        int resultMax = Hashing.consistentHash(Long.MAX_VALUE, 100);
        assertTrue(resultMax >= 0 && resultMax < 100);

        // Test with min long
        int resultMin = Hashing.consistentHash(Long.MIN_VALUE, 100);
        assertTrue(resultMin >= 0 && resultMin < 100);

        // Test a value that will definitely overflow when multiplied
        long overflowCandidate = Long.MAX_VALUE / 2;
        int resultOverflow = Hashing.consistentHash(overflowCandidate, 50);
        assertTrue(resultOverflow >= 0 && resultOverflow < 50);
    }

    @Test
    public void testConsistentHash_multipleLoopIterations() {
        // Test cases that require multiple iterations through the while loop
        // These inputs were chosen to exercise the loop multiple times

        // With small buckets, the loop should exit quickly
        assertEquals(0, Hashing.consistentHash(0L, 1));
        assertEquals(0, Hashing.consistentHash(1L, 1));

        // Test with various inputs to ensure the algorithm works correctly
        // Instead of hardcoding specific values, test properties
        int buckets = 10;
        for (long input = 0; input < 100; input++) {
            int result = Hashing.consistentHash(input, buckets);
            assertTrue("Result " + result + " out of range for input=" + input,
                    result >= 0 && result < buckets);
        }

        // Test with more buckets to ensure multiple jumps
        int result = Hashing.consistentHash(999999L, 1000);
        assertTrue(result >= 0 && result < 1000);

        // Test that the function is deterministic for a few specific values
        // (but don't hardcode the exact results)
        long[] testInputs = {1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L, 10L};
        for (long input : testInputs) {
            int first = Hashing.consistentHash(input, buckets);
            int second = Hashing.consistentHash(input, buckets);
            assertEquals("Result should be deterministic for input=" + input, first, second);
            assertTrue("Result should be in range for input=" + input, first >= 0 && first < buckets);
        }
    }

    @Test
    public void testConsistentHash_stateCalculation() {
        // Specifically test the inlined state calculation for various inputs
        // This ensures the inlined version matches what LinearCongruentialGenerator did

        // Test a sequence of inputs to ensure deterministic behavior
        int buckets = 20;
        java.util.Map<Long, Integer> results = new java.util.HashMap<>();

        for (long input = 0; input < 100; input++) {
            int result = Hashing.consistentHash(input, buckets);
            assertTrue(result >= 0 && result < buckets);

            // Verify determinism
            if (results.containsKey(input)) {
                assertEquals(results.get(input).intValue(), result);
            } else {
                results.put(input, result);
            }

            // Verify the same result when called again
            assertEquals(result, Hashing.consistentHash(input, buckets));
        }

        // Test negative inputs similarly
        for (long input = -100; input < 0; input++) {
            int result = Hashing.consistentHash(input, buckets);
            assertTrue(result >= 0 && result < buckets);
            assertEquals(result, Hashing.consistentHash(input, buckets));
        }
    }

    @Test
    public void testConsistentHash_hashCodeOverload() {
        // Test the overload that takes a HashCode.
        HashCode hashCode = Hashing.murmur3_32().hashLong(42L);
        int buckets = 20;
        int result1 = Hashing.consistentHash(hashCode, buckets);
        // The HashCode overload should delegate to the long overload with hashCode.padToLong().
        int result2 = Hashing.consistentHash(hashCode.padToLong(), buckets);
        assertEquals(result1, result2);

        // Test with different hash functions
        HashCode[] hashCodes = {
            Hashing.murmur3_32().hashInt(42),
            Hashing.murmur3_32().hashString("test", java.nio.charset.StandardCharsets.UTF_8),
            Hashing.murmur3_128().hashLong(42L),
            Hashing.sha256().hashInt(42)
        };

        for (HashCode hc : hashCodes) {
            int r1 = Hashing.consistentHash(hc, buckets);
            int r2 = Hashing.consistentHash(hc.padToLong(), buckets);
            assertEquals(r1, r2);
